const listHomeEntries = `-- name: ListHomeEntries :many

SELECT e.id, e.kind, e.status_id, e.author_account_id, e.author_domain, e.original_author_account_id,
  e.original_author_domain, e.visibility, e.is_local, e.language, e.revision_seq, e.is_reply
FROM feed_entries e
WHERE e.author_account_id IN (
    SELECT f.followee_account_id FROM feed_follow_edges f WHERE f.follower_account_id = ?1
    UNION ALL SELECT CAST(?1 AS TEXT))
  AND (CAST(?2 AS TEXT) = '' OR e.id < CAST(?2 AS TEXT))
  AND e.id >= CAST(?3 AS TEXT)
  AND (e.kind = 'post' OR e.author_account_id = ?1 OR EXISTS (
    SELECT 1 FROM feed_follow_edges f
    WHERE f.follower_account_id = ?1 AND f.followee_account_id = e.author_account_id AND f.show_boosts = 1))
  AND (e.visibility <> 'direct' OR e.author_account_id = ?1 OR EXISTS (
    SELECT 1 FROM feed_direct_recipients d WHERE d.recipient_account_id = ?1 AND d.entry_id = e.id))
  AND NOT EXISTS (
    SELECT 1 FROM feed_exclusions x
    WHERE x.viewer_account_id = ?1
      AND x.target_account_id IN (e.author_account_id, e.original_author_account_id)
      AND (x.expires_at IS NULL OR x.expires_at > CAST(?4 AS INTEGER)))
  AND NOT EXISTS (
    SELECT 1 FROM feed_author_restrictions r
    WHERE r.account_id IN (e.author_account_id, e.original_author_account_id) AND r.restriction = 'profile_view'
      AND (r.effective_until IS NULL OR r.effective_until > CAST(?4 AS INTEGER)))
  AND NOT EXISTS (
    SELECT 1 FROM feed_domain_restrictions dr
    WHERE dr.restriction = 'profile_view'
      AND (dr.effective_until IS NULL OR dr.effective_until > CAST(?4 AS INTEGER))
      AND (dr.domain IN (e.author_domain, e.original_author_domain)
        OR substr(e.author_domain, -(length(dr.domain) + 1)) = '.' || dr.domain
        OR substr(e.original_author_domain, -(length(dr.domain) + 1)) = '.' || dr.domain))
  AND NOT EXISTS (
    SELECT 1 FROM feed_domain_mutes dm
    WHERE dm.viewer_account_id = ?1 AND e.kind = 'boost' AND e.author_account_id <> ?1
      AND (dm.domain = e.original_author_domain OR substr(e.original_author_domain, -(length(dm.domain) + 1)) = '.' || dm.domain))
  AND (CAST(?5 AS INTEGER) = 1 OR e.language = 'und' OR e.language IN (SELECT value FROM json_each(CAST(?6 AS TEXT))))
ORDER BY e.id DESC
LIMIT ?7
`

type ListHomeEntriesParams struct {
	Viewer       string
	Before       string
	WindowFloor  string
	Now          int64
	AllLanguages int64
	Languages    string
	PageLimit    int64
}

// Timelines (data-model 6) ----------------------------------------------------------------------
// A list argument is a JSON array of strings, read with json_each: the SQLite engine of sqlc
// expands sqlc.slice into plain ? placeholders, which SQLite numbers after the largest ?N, so a
// slice followed by another argument would bind the wrong values.
// before = ” starts at the newest entry. A language filter applies when all_languages is 0:
// entries in an undetermined language ('und') always pass. A restriction or mute applies while
// its end is NULL or after now. A domain restriction also covers the subdomains of its domain.
// ListHomeEntries is the home timeline (FR-201) of a viewer: the posts of the viewer and of the
// accounts the viewer follows, their boosts unless the follow hides them, and the viewer's own
// boosts, within the read window (id >= window_floor).
func (q *Queries) ListHomeEntries(ctx context.Context, arg ListHomeEntriesParams) ([]FeedEntry, error) {
	rows, err := q.db.QueryContext(ctx, listHomeEntries,
		arg.Viewer,
		arg.Before,
		arg.WindowFloor,
		arg.Now,
		arg.AllLanguages,
		arg.Languages,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []FeedEntry{}
	for rows.Next() {
		var i FeedEntry
		if err := rows.Scan(
			&i.ID,
			&i.Kind,
			&i.StatusID,
			&i.AuthorAccountID,
			&i.AuthorDomain,
			&i.OriginalAuthorAccountID,
			&i.OriginalAuthorDomain,
			&i.Visibility,
			&i.IsLocal,
			&i.Language,
			&i.RevisionSeq,
			&i.IsReply,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

