const listTagUsageOf = `-- name: ListTagUsageOf :many
SELECT tag_id, statuses_count, last_used_at FROM tag_usage WHERE tag_id IN (/*SLICE:ids*/?) ORDER BY tag_id
`

// ListTagUsageOf returns the usage of the tags among ids that have a row.
func (q *Queries) ListTagUsageOf(ctx context.Context, ids []string) ([]TagUsage, error) {
	query := listTagUsageOf
	var queryParams []interface{}
	if len(ids) > 0 {
		for _, v := range ids {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:ids*/?", strings.Repeat(",?", len(ids))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:ids*/?", "NULL", 1)
	}
	rows, err := q.db.QueryContext(ctx, query, queryParams...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TagUsage{}
	for rows.Next() {
		var i TagUsage
		if err := rows.Scan(&i.TagID, &i.StatusesCount, &i.LastUsedAt); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateFeedEntriesRevision = `-- name: UpdateFeedEntriesRevision :execrows
UPDATE feed_entries SET language = ?1, revision_seq = ?2
WHERE status_id = ?3 AND revision_seq < ?2
`

type UpdateFeedEntriesRevisionParams struct {
	Language    string
	RevisionSeq int64
	StatusID    string
}

// UpdateFeedEntriesRevision moves the entries of a status (the post and its boosts) to a
// newer revision; an older or repeated revision changes nothing.
func (q *Queries) UpdateFeedEntriesRevision(ctx context.Context, arg UpdateFeedEntriesRevisionParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, updateFeedEntriesRevision, arg.Language, arg.RevisionSeq, arg.StatusID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

